const store = $getWorkflowStaticData('global');
const cfg = $('CONFIG').first().json;
const now = new Date().toISOString();

if (!store.dialer) {
  store.dialer = {
    initialized_at: now,
    from_pool_index: 0,
    leads: {},
    attempts: {},
    callControlToAttempt: {},
    callLegToAttempt: {},
    eventLedger: {},
    commandLedger: {},
    logs: [],
  };
}

const seedLeads = [
  {
    lead_id: 'lead-001',
    full_name: 'Replace With Test Lead 1',
    company: 'Replace With Company 1',
    phone: '+15550000001',
    timezone: 'America/Chicago',
    notes: 'Safe first test call. Replace this node with Google Sheets or your database later.',
  },
  {
    lead_id: 'lead-002',
    full_name: 'Replace With Test Lead 2',
    company: 'Replace With Company 2',
    phone: '+15550000002',
    timezone: 'America/New_York',
    notes: 'Only call numbers you are allowed to dial.',
  },
  {
    lead_id: 'lead-003',
    full_name: 'Replace With Test Lead 3',
    company: 'Replace With Company 3',
    phone: '+15550000003',
    timezone: 'America/Denver',
    notes: 'Replace this placeholder list with your real lead source.',
  },
];

for (const lead of seedLeads) {
  if (!store.dialer.leads[lead.lead_id]) {
    store.dialer.leads[lead.lead_id] = {
      ...lead,
      status: 'ready',
      completed: false,
      attempts_count: 0,
      next_eligible_at: null,
      current_attempt_id: null,
      last_outcome: null,
      created_at: now,
      updated_at: now,
    };
  }
}

const summary = Object.values(store.dialer.leads).map((lead) => ({
  lead_id: lead.lead_id,
  phone: lead.phone,
  status: lead.status,
  attempts_count: lead.attempts_count,
  next_eligible_at: lead.next_eligible_at,
  completed: lead.completed,
}));

return [{
  json: {
    config_snapshot: cfg,
    seeded_count: summary.length,
    leads: summary,
    note: 'Replace this node with Google Sheets or a DB query when you are ready.',
  },
}];

const store = $getWorkflowStaticData('global');
const cfg = $('CONFIG').first().json;
const dialer = store.dialer || { leads: {}, attempts: {}, logs: [], from_pool_index: 0 };
const now = new Date();

// ============================================
// 🛑 LOOP BREAKER: THE KILL SWITCH
// ============================================
const currentStatus = $json.dialer_status || (typeof $('Supabase Get Status') !== 'undefined' && $('Supabase Get Status').first()?.json?.dialer_status);

if (currentStatus === 'stopped' || currentStatus === 'stopping') {
  dialer.logs.push({ at: new Date().toISOString(), message: 'User stopped the dialer. Breaking loop.' });
  return [{ 
     json: { 
        shouldDial: false, 
        reason: 'user_stopped',
        message: 'Loop artificially broken by Supabase Kill Switch.' 
     } 
  }];
}
// ============================================

const pushLog = (message, extra = {}) => {
  dialer.logs = dialer.logs || [];
  dialer.logs.push({ at: new Date().toISOString(), message, ...extra });
  dialer.logs = dialer.logs.slice(-500);
};

const activeStatuses = new Set(['dialing', 'calling', 'answered_pending_amd', 'transfer_requested', 'live_transferred']);
const staleCutoff = Date.now() - 2 * 60 * 60 * 1000;
for (const attempt of Object.values(dialer.attempts || {})) {
  if (activeStatuses.has(attempt.status) && attempt.started_at && new Date(attempt.started_at).getTime() < staleCutoff) {
    attempt.status = 'stale';
    attempt.updated_at = new Date().toISOString();
  }
}

const activeAttemptCount = Object.values(dialer.attempts || {}).filter((attempt) => activeStatuses.has(attempt.status)).length;
if (activeAttemptCount >= Number(cfg.MAX_CONCURRENT_CALLS || 1)) {
  pushLog('Concurrency limit reached, skipping dial cycle.', { activeAttemptCount });
  return [{ json: { shouldDial: false, reason: 'max_concurrent_calls_reached', activeAttemptCount } }];
}

if (cfg.ENFORCE_ALLOWED_HOURS) {
  const hour = now.getHours();
  const start = Number(cfg.ALLOWED_HOURS_START_LOCAL ?? 8);
  const end = Number(cfg.ALLOWED_HOURS_END_LOCAL ?? 20);
  const allowed = start <= end ? hour >= start && hour < end : hour >= start || hour < end;
  if (!allowed) {
    pushLog('Outside allowed dialing window.', { hour, start, end });
    return [{ json: { shouldDial: false, reason: 'outside_allowed_hours', hour, start, end } }];
  }
}

const eligibleLeads = Object.values(dialer.leads || {})
  .filter((lead) => !lead.completed)
  .filter((lead) => Number(lead.attempts_count || 0) < Number(cfg.MAX_ATTEMPTS_PER_LEAD || 1))
  .filter((lead) => !lead.next_eligible_at || new Date(lead.next_eligible_at).getTime() <= Date.now())
  .filter((lead) => !lead.status || !activeStatuses.has(lead.status))
  .sort((a, b) => {
    const aTime = a.updated_at ? new Date(a.updated_at).getTime() : 0;
    const bTime = b.updated_at ? new Date(b.updated_at).getTime() : 0;
    if (a.attempts_count !== b.attempts_count) return a.attempts_count - b.attempts_count;
    return aTime - bTime;
  });

if (!eligibleLeads.length) {
  pushLog('No eligible leads found for this dial cycle.');
  return [{ json: { shouldDial: false, reason: 'no_eligible_leads', activeAttemptCount } }];
}

const lead = eligibleLeads[0];
const pool = Array.isArray(cfg.FROM_NUMBER_POOL) ? cfg.FROM_NUMBER_POOL.filter(Boolean) : [];
if (!pool.length) {
  throw new Error('CONFIG.FROM_NUMBER_POOL must contain at least one number.');
}

const fromIndex = Number(dialer.from_pool_index || 0) % pool.length;
const chosenFrom = pool[fromIndex];
dialer.from_pool_index = fromIndex + 1;

const attemptId = [Date.now().toString(36), Math.random().toString(36).slice(2, 10), Math.random().toString(36).slice(2, 10)].join('-');
const clientStatePayload = {
  workflow: 'telnyx_power_dialer',
  lead_id: lead.lead_id,
  attempt_id: attemptId,
  created_at: new Date().toISOString(),
};
const clientState = Buffer.from(JSON.stringify(clientStatePayload), 'utf8').toString('base64');

lead.status = 'dialing';
lead.current_attempt_id = attemptId;
lead.updated_at = new Date().toISOString();

pushLog('Selected next eligible lead.', {
  lead_id: lead.lead_id,
  attempt_id: attemptId,
  from: chosenFrom,
  to: lead.phone,
});

return [{
  json: {
    shouldDial: true,
    lead_id: lead.lead_id,
    lead_phone: lead.phone,
    lead_name: lead.full_name,
    company: lead.company,
    attempts_count: lead.attempts_count,
    chosen_from: chosenFrom,
    attempt_id: attemptId,
    command_id: attemptId,
    client_state: clientState,
    client_state_payload: clientStatePayload,
    webhook_hint: `Set your Telnyx Voice API Application webhook to /webhook/${cfg.WEBHOOK_PATH}?token=${cfg.WEBHOOK_TOKEN}`,
  },
}];

return [{
  json: {
    ok: true,
    skipped: true,
    reason: $json.reason || 'no_action',
    message: 'Dialer loop exited without placing a call.',
  },
}];

const store = $getWorkflowStaticData('global');
const dialer = store.dialer;
const selected = $('Select Next Eligible Lead').first().json;
const response = $json;
const cfg = $('CONFIG').first().json;
const now = new Date().toISOString();

const pushLog = (message, extra = {}) => {
  dialer.logs = dialer.logs || [];
  dialer.logs.push({ at: now, message, ...extra });
  dialer.logs = dialer.logs.slice(-500);
};

const body = response.data ? response.data : response;
const lead = dialer.leads[selected.lead_id];
if (!lead) {
  return [{ json: { ok: false, error: 'Lead not found while persisting attempt.' } }];
}

const callControlId = body.call_control_id || body.data?.call_control_id || null;
const callLegId = body.call_leg_id || body.data?.call_leg_id || null;
const callSessionId = body.call_session_id || body.data?.call_session_id || null;

if (!callControlId) {
  lead.status = 'ready';
  lead.current_attempt_id = null;
  lead.last_outcome = 'dial_request_failed';
  lead.next_eligible_at = new Date(Date.now() + Number(cfg.COOLDOWN_MINUTES || 60) * 60 * 1000).toISOString();
  lead.updated_at = now;
  dialer.attempts[selected.attempt_id] = {
    attempt_id: selected.attempt_id,
    lead_id: selected.lead_id,
    to: selected.lead_phone,
    from: selected.chosen_from,
    started_at: now,
    updated_at: now,
    status: 'dial_request_failed',
    raw_response: response,
  };
  pushLog('Dial request failed before a call_control_id was returned.', {
    lead_id: selected.lead_id,
    attempt_id: selected.attempt_id,
  });
  return [{
    json: {
      ok: false,
      lead_id: selected.lead_id,
      attempt_id: selected.attempt_id,
      status: 'dial_request_failed',
      next_eligible_at: lead.next_eligible_at,
    },
  }];
}

lead.attempts_count = Number(lead.attempts_count || 0) + 1;
lead.status = 'calling';
lead.current_attempt_id = selected.attempt_id;
lead.updated_at = now;

dialer.attempts[selected.attempt_id] = {
  attempt_id: selected.attempt_id,
  lead_id: selected.lead_id,
  command_id: selected.command_id,
  call_control_id: callControlId,
  call_leg_id: callLegId,
  call_session_id: callSessionId,
  to: selected.lead_phone,
  from: selected.chosen_from,
  started_at: now,
  updated_at: now,
  status: 'calling',
  outcome: null,
  finalised: false,
  raw_response: response,
};

dialer.callControlToAttempt[callControlId] = selected.attempt_id;
if (callLegId) dialer.callLegToAttempt[callLegId] = selected.attempt_id;

pushLog('Dial initiated successfully.', {
  lead_id: selected.lead_id,
  attempt_id: selected.attempt_id,
  call_control_id: callControlId,
  to: selected.lead_phone,
});

return [{
  json: {
    ok: true,
    lead_id: selected.lead_id,
    attempt_id: selected.attempt_id,
    call_control_id: callControlId,
    call_leg_id: callLegId,
    call_session_id: callSessionId,
    status: 'calling',
  },
}];

const cfg = $('CONFIG').first().json;
const body = $json.body || {};
const headers = $json.headers || {};
const query = $json.query || {};

const event = body.data || {};
const payload = event.payload || {};
const token = query.token || '';
const tokenValid = token === cfg.WEBHOOK_TOKEN;

return [{
  json: {
    token_valid: tokenValid,
    debug_mode: Boolean(cfg.DEBUG_MODE),
    raw_webhook: cfg.DEBUG_MODE ? body : null,
    headers,
    query,
    event_id: event.id || null,
    event_type: event.event_type || null,
    occurred_at: event.occurred_at || null,
    call_control_id: payload.call_control_id || null,
    call_leg_id: payload.call_leg_id || null,
    call_session_id: payload.call_session_id || null,
    connection_id: payload.connection_id || null,
    from: payload.from || null,
    to: payload.to || null,
    amd_result: payload.result || null,
    hangup_cause: payload.hangup_cause || null,
    hangup_source: payload.hangup_source || null,
    sip_hangup_cause: payload.sip_hangup_cause || null,
    client_state: payload.client_state || null,
    payload,
  },
}];

const store = $getWorkflowStaticData('global');
const dialer = store.dialer || { leads: {}, attempts: {}, callControlToAttempt: {}, callLegToAttempt: {}, eventLedger: {}, logs: [] };
store.dialer = dialer;
const cfg = $('CONFIG').first().json;
const input = $json;
const nowIso = new Date().toISOString();

const pushLog = (message, extra = {}) => {
  dialer.logs = dialer.logs || [];
  dialer.logs.push({ at: nowIso, message, ...extra });
  dialer.logs = dialer.logs.slice(-500);
};

if (cfg.DEBUG_MODE) {
  pushLog('Webhook received.', {
    event_type: input.event_type,
    event_id: input.event_id,
    call_control_id: input.call_control_id,
    raw: input.raw_webhook,
  });
}

const dedupeKey = input.event_id || `${input.event_type || 'unknown'}::${input.call_control_id || 'no-call-control'}::${input.occurred_at || nowIso}`;
if (dialer.eventLedger[dedupeKey]) {
  pushLog('Duplicate webhook ignored.', { dedupeKey, event_type: input.event_type });
  return [{ json: { skip: true, reason: 'duplicate_event', dedupe_key: dedupeKey, action: 'none', event_type: input.event_type } }];
}
dialer.eventLedger[dedupeKey] = nowIso;

const decodeClientState = (value) => {
  if (!value) return null;
  try {
    return JSON.parse(Buffer.from(value, 'base64').toString('utf8'));
  } catch {
    return null;
  }
};

const clientState = decodeClientState(input.client_state);
let attemptId = dialer.callControlToAttempt[input.call_control_id] || dialer.callLegToAttempt[input.call_leg_id] || clientState?.attempt_id || null;
const leadId = clientState?.lead_id || null;

if (!attemptId && input.event_type === 'call.initiated' && clientState?.attempt_id) {
  attemptId = clientState.attempt_id;
}

const existingAttempt = attemptId ? dialer.attempts[attemptId] : null;
if (!existingAttempt && attemptId && leadId) {
  dialer.attempts[attemptId] = {
    attempt_id: attemptId,
    lead_id: leadId,
    status: 'calling',
    started_at: nowIso,
    updated_at: nowIso,
    outcome: null,
    finalised: false,
  };
}

const liveAttempt = existingAttempt || (attemptId ? dialer.attempts[attemptId] : null);
if (!liveAttempt) {
  pushLog('Unknown webhook event received; no mapped attempt found.', {
    event_type: input.event_type,
    call_control_id: input.call_control_id,
  });
  return [{ json: { skip: true, reason: 'unknown_attempt', dedupe_key: dedupeKey, action: 'none', event_type: input.event_type } }];
}

const lead = dialer.leads[liveAttempt.lead_id];
if (!lead) {
  pushLog('Mapped attempt exists but lead record is missing.', {
    attempt_id: liveAttempt.attempt_id,
    lead_id: liveAttempt.lead_id,
  });
  return [{ json: { skip: true, reason: 'unknown_lead', dedupe_key: dedupeKey, action: 'none', event_type: input.event_type } }];
}

if (input.call_control_id) dialer.callControlToAttempt[input.call_control_id] = liveAttempt.attempt_id;
if (input.call_leg_id) dialer.callLegToAttempt[input.call_leg_id] = liveAttempt.attempt_id;
liveAttempt.call_control_id = input.call_control_id || liveAttempt.call_control_id || null;
liveAttempt.call_leg_id = input.call_leg_id || liveAttempt.call_leg_id || null;
liveAttempt.call_session_id = input.call_session_id || liveAttempt.call_session_id || null;
liveAttempt.updated_at = nowIso;
liveAttempt.last_event_type = input.event_type;
liveAttempt.last_event_at = input.occurred_at || nowIso;
lead.updated_at = nowIso;

const classifyHangup = (payload) => {
  const cause = String(payload.hangup_cause || '').toLowerCase();
  const sip = String(payload.sip_hangup_cause || '');
  if (cause.includes('busy') || sip === '486') return 'busy';
  if (cause.includes('no_answer') || cause.includes('timeout') || sip === '480' || sip === '487') return 'no_answer';
  if (cause.includes('rejected') || cause.includes('blocked') || sip === '603') return 'failed';
  return 'hangup';
};

const scheduleRetry = (outcome) => {
  lead.status = 'retry_scheduled';
  lead.last_outcome = outcome;
  lead.next_eligible_at = new Date(Date.now() + Number(cfg.COOLDOWN_MINUTES || 60) * 60 * 1000).toISOString();
};

let action = 'none';
let actionReason = null;

switch (input.event_type) {
  case 'call.initiated':
    liveAttempt.status = 'calling';
    lead.status = 'calling';
    break;

  case 'call.answered':
    liveAttempt.status = 'answered_pending_amd';
    lead.status = 'answered_pending_amd';
    break;

  case 'call.machine.detection.ended': {
    const result = String(input.amd_result || '').toLowerCase();
    liveAttempt.amd_result = result;
    if (['human', 'not_sure'].includes(result)) {
      liveAttempt.status = 'transfer_requested';
      liveAttempt.outcome = result === 'human' ? 'human' : 'human_not_sure';
      lead.status = 'transfer_requested';
      lead.last_outcome = liveAttempt.outcome;
      action = 'transfer';
      actionReason = liveAttempt.outcome;
    } else if (['machine'].includes(result)) {
      liveAttempt.status = 'hangup_requested';
      liveAttempt.outcome = 'voicemail';
      liveAttempt.finalised = true;
      lead.last_outcome = 'voicemail';
      scheduleRetry('voicemail');
      action = 'hangup';
      actionReason = 'voicemail';
    }
    break;
  }

  case 'call.machine.premium.detection.ended': {
    const result = String(input.amd_result || '').toLowerCase();
    liveAttempt.amd_result = result;
    if (['human_residence', 'human_business', 'not_sure'].includes(result)) {
      liveAttempt.status = 'transfer_requested';
      liveAttempt.outcome = result;
      lead.status = 'transfer_requested';
      lead.last_outcome = result;
      action = 'transfer';
      actionReason = result;
    } else if (['machine', 'silence', 'fax_detected'].includes(result)) {
      liveAttempt.status = 'hangup_requested';
      liveAttempt.outcome = result === 'machine' ? 'voicemail' : result;
      liveAttempt.finalised = true;
      lead.last_outcome = liveAttempt.outcome;
      scheduleRetry(liveAttempt.outcome);
      action = 'hangup';
      actionReason = liveAttempt.outcome;
    }
    break;
  }

  case 'call.bridged':
    liveAttempt.status = 'live_transferred';
    liveAttempt.outcome = liveAttempt.outcome || 'human_connected';
    lead.status = 'connected';
    lead.completed = true;
    lead.last_outcome = 'human_connected';
    lead.next_eligible_at = null;
    break;

  case 'call.hangup': {
    const outcome = classifyHangup(input.payload || {});
    liveAttempt.status = 'hangup';
    liveAttempt.hangup_cause = input.hangup_cause || null;
    liveAttempt.hangup_source = input.hangup_source || null;
    if (!lead.completed && !liveAttempt.finalised) {
      if (['busy', 'no_answer', 'failed', 'hangup'].includes(outcome)) {
        liveAttempt.outcome = outcome;
        liveAttempt.finalised = true;
        scheduleRetry(outcome);
      }
    }
    if (lead.completed) {
      lead.status = 'completed';
      lead.next_eligible_at = null;
    }
    break;
  }

  default:
    break;
}

const actionClientState = Buffer.from(JSON.stringify({
  workflow: 'telnyx_power_dialer',
  lead_id: liveAttempt.lead_id,
  attempt_id: liveAttempt.attempt_id,
  action,
}), 'utf8').toString('base64');

pushLog('Webhook processed.', {
  event_type: input.event_type,
  lead_id: liveAttempt.lead_id,
  attempt_id: liveAttempt.attempt_id,
  action,
  actionReason,
});

return [{
  json: {
    skip: false,
    dedupe_key: dedupeKey,
    event_type: input.event_type,
    action,
    action_reason: actionReason,
    action_client_state: actionClientState,
    attempt_id: liveAttempt.attempt_id,
    lead_id: liveAttempt.lead_id,
    call_control_id: liveAttempt.call_control_id,
    lead_phone: lead.phone,
    lead_status: lead.status,
    lead_completed: lead.completed,
    attempt_status: liveAttempt.status,
    outcome: liveAttempt.outcome,
  },
}];

const store = $getWorkflowStaticData('global');
const dialer = store.dialer;
const processed = $('Process Webhook State Machine').first().json;
const response = $json;
const now = new Date().toISOString();
const attempt = dialer.attempts[processed.attempt_id];
const lead = dialer.leads[processed.lead_id];

const pushLog = (message, extra = {}) => {
  dialer.logs = dialer.logs || [];
  dialer.logs.push({ at: now, message, ...extra });
  dialer.logs = dialer.logs.slice(-500);
};

attempt.updated_at = now;
attempt.transfer_command_response = response;

if ((response.data && response.data.result === 'ok') || response.result === 'ok') {
  attempt.status = 'transfer_requested';
  lead.status = 'transfer_requested';
  pushLog('Transfer command accepted by Telnyx.', { attempt_id: processed.attempt_id, call_control_id: processed.call_control_id });
} else {
  attempt.status = 'transfer_failed';
  attempt.finalised = true;
  attempt.outcome = 'transfer_failed';
  lead.status = 'retry_scheduled';
  lead.last_outcome = 'transfer_failed';
  lead.next_eligible_at = new Date(Date.now() + Number($('CONFIG').first().json.COOLDOWN_MINUTES || 60) * 60 * 1000).toISOString();
  pushLog('Transfer command failed; lead moved back to retry queue.', { attempt_id: processed.attempt_id, response });
}

return [{ json: { ok: true, action: 'transfer', attempt_id: processed.attempt_id, lead_id: processed.lead_id } }];

const store = $getWorkflowStaticData('global');
const dialer = store.dialer;
const processed = $('Process Webhook State Machine').first().json;
const response = $json;
const now = new Date().toISOString();
const attempt = dialer.attempts[processed.attempt_id];
const lead = dialer.leads[processed.lead_id];

const pushLog = (message, extra = {}) => {
  dialer.logs = dialer.logs || [];
  dialer.logs.push({ at: now, message, ...extra });
  dialer.logs = dialer.logs.slice(-500);
};

attempt.updated_at = now;
attempt.hangup_command_response = response;
attempt.status = 'hangup_requested';
attempt.finalised = true;

if ((response.data && response.data.result === 'ok') || response.result === 'ok') {
  pushLog('Hangup command accepted by Telnyx.', { attempt_id: processed.attempt_id, call_control_id: processed.call_control_id });
} else {
  pushLog('Hangup command returned a non-ok response.', { attempt_id: processed.attempt_id, response });
}

if (!lead.completed) {
  lead.status = 'retry_scheduled';
  lead.last_outcome = processed.outcome || 'hangup_requested';
  lead.next_eligible_at = lead.next_eligible_at || new Date(Date.now() + Number($('CONFIG').first().json.COOLDOWN_MINUTES || 60) * 60 * 1000).toISOString();
}

return [{ json: { ok: true, action: 'hangup', attempt_id: processed.attempt_id, lead_id: processed.lead_id } }];

return [{
  json: {
    ok: true,
    action: 'none',
    message: 'Webhook updated state without requiring a Telnyx command.',
    event_type: $('Process Webhook State Machine').first().json.event_type || null,
  },
}];
